const examples=['“มีอำนาจ” กับ “มีหน้าที่” ต่างกันอย่างไร','หนังสือเวียนมีผลผูกพันแค่ไหน','กฎหมายแม่บทกับกฎหมายลำดับรอง'];
function home(){return `<section class="hero"><div class="eyebrow">THAI LEGAL WISDOM · อาจารย์กฎหมาย AI</div><h1>เข้าใจกฎหมายอย่างลึกซึ้ง<br><em>นำไปใช้ได้อย่างมั่นใจ</em></h1><p>ผู้ช่วยเรียนรู้และวิเคราะห์กฎหมายไทยอย่างเป็นระบบ<br>จากภาษากฎหมายที่ซับซ้อน สู่ความเข้าใจที่นำไปใช้ได้จริง</p><div class="hero-art">${art}</div></section><div class="workspace"><section class="panel analysis"><div class="sectionhead"><span class="iconbox">▧</span><div><h2>วันนี้คุณมีประเด็นกฎหมายอะไร?</h2><p class="subtitle">เริ่มต้นจากคำถาม สถานการณ์ หรือบทบัญญัติที่ต้องการทำความเข้าใจ</p></div></div><div class="step-label"><span>1</span> เลือกรูปแบบการอธิบาย</div><div class="modes">${modes.map((m,i)=>`<button class="mode ${i===mode?'selected':''}" data-mode="${i}" aria-pressed="${i===mode}"><span>${['♙','▥','♧'][i]}</span><b>${m}</b><small>${['เข้าใจง่าย ใกล้ตัว ใช้ได้จริง','วิเคราะห์อำนาจ หน้าที่ และแนวปฏิบัติ','เจาะลึกหลักการและความสัมพันธ์'][i]}</small></button>`).join('')}</div><label for="question" class="step-label"><span>2</span> ระบุคำถามหรือข้อเท็จจริงของคุณ</label><div class="fieldwrap"><textarea id="question" maxlength="12000" placeholder="เช่น คำว่า ‘ให้มีอำนาจ’ กับ ‘มีหน้าที่ต้องดำเนินการ’ ในกฎหมาย แตกต่างกันอย่างไร?\n\nหรือวางข้อความกฎหมายที่คุณต้องการให้ช่วยอธิบาย…">${esc(question)}</textarea><div class="fieldbottom"><button class="textbutton" id="upload">♧ แนบเอกสารข้อความ <span style="font-size:8px">.txt / .md</span></button><span id="counter">${question.length.toLocaleString()} / 12,000</span></div></div><input type="file" id="file" accept=".txt,.md,text/plain,text/markdown" hidden><div class="doc-label" id="doc-label">${docName?`▤ ${esc(docName)} <button class="textbutton" id="remove-doc">นำออก ×</button>`:''}</div><div class="examples">${examples.map((e,i)=>`<button class="chip" data-example="${i}">${e}</button>`).join('')}</div><div class="submitrow"><span>◇ เตรียมคำสั่งตามกรอบวิเคราะห์ 6 ขั้นตอน<br>สำหรับนำไปใช้ต่อใน ChatGPT</span><button class="primary" id="analyze">เตรียมวิเคราะห์กฎหมาย <span class="arrow">→</span></button></div></section><aside class="panel guide"><span class="eyebrow">A PRINCIPLED APPROACH</span><h2>เข้าใจทุกมิติของกฎหมาย</h2><p>กรอบการวิเคราะห์อย่างเป็นระบบ<br>ตั้งแต่ประเด็นปัญหาสู่แนวทางปฏิบัติ</p>${[['ระบุประเด็นกฎหมาย','แยกคำถาม สิทธิ หน้าที่ และอำนาจ'],['ตรวจสอบแหล่งกฎหมาย','อ้างอิงตัวบทและแหล่งข้อมูลทางการ'],['วิเคราะห์บทบัญญัติ','แยกองค์ประกอบ เงื่อนไข ข้อยกเว้น'],['ตีความและเชื่อมโยง','มองความสัมพันธ์ของกฎหมาย'],['ประยุกต์กับข้อเท็จจริง','พิจารณากฎหมายกับสถานการณ์จริง'],['สรุปแนวทางปฏิบัติ','เข้าใจง่าย พร้อมข้อควรระวัง']].map((p,i)=>`<div class="process"><span class="number">0${i+1}</span><div><b>${p[0]}</b><small>${p[1]}</small></div></div>`).join('')}<div class="guide-note">✓ ยึดหลักความถูกต้อง เป็นกลาง และตรวจสอบได้</div></aside></div><div class="bottom-heading"><h2>เติมพื้นฐาน ก่อนลงลึก</h2><button class="textbutton" data-page="library">สำรวจคลังความรู้ <span style="margin-left:9px">↗</span></button></div><div class="resource-cards">${[['§','พื้นฐานกฎหมาย','ลำดับศักดิ์และฐานอำนาจ','เข้าใจความสัมพันธ์ของกฎหมายแต่ละระดับ','library'],['◇','หลักนิติศาสตร์','6 มิติของการตีความกฎหมาย','อ่านให้รอบด้าน มองให้เห็นมากกว่าตัวอักษร','principles'],['⚙','พร้อมนำไปใช้','อาจารย์กฎหมายในแบบของคุณ','นำ Custom Instructions ไปใช้กับ GPT ของคุณ','instructions']].map(r=>`<button class="resource" data-page="${r[4]}"><span class="r-icon">${r[0]}</span><span class="tag">${r[1]}</span><h3>${r[2]}</h3><p>${r[3]}</p><span class="goto">เรียนรู้เพิ่มเติม <span style="float:right">↗</span></span></button>`).join('')}</div><p class="notice"><span>ⓘ</span> แอปนี้จัดเตรียมคำสั่งและบริบท ยังไม่มีโมเดล AI หรือระบบตรวจสอบกฎหมายปัจจุบันในตัว กรุณาตรวจสอบตัวบทกับแหล่งข้อมูลทางการก่อนนำไปใช้</p>`}
function intro(title,sub){return `<div class="pageintro"><span class="eyebrow">THAI LEGAL WISDOM / KNOWLEDGE</span><h1>${title}</h1><p>${sub}</p></div>`}
function library(){return intro('คลังความรู้กฎหมาย','เริ่มจากหลักคิดที่ถูกต้อง แล้วค่อยเชื่อมโยงสู่การปฏิบัติ')+`<div class="knowledge-grid"><article class="panel knowledge"><h3>ลำดับศักดิ์และฐานอำนาจ</h3><p>รัฐธรรมนูญเป็นกฎหมายสูงสุด ส่วนกฎหมายระดับพระราชบัญญัติ ประมวลกฎหมาย และพระราชกำหนด ต้องพิจารณาฐานะและเงื่อนไขตามรัฐธรรมนูญ กฎหมายลำดับรองต้องออกโดยผู้มีอำนาจและอยู่ภายในขอบเขตของกฎหมายแม่บท</p><p>พระราชกฤษฎีกา กฎกระทรวง และข้อกำหนดอื่นต้องตรวจสอบฐานอำนาจเป็นรายฉบับ ชื่อเอกสารเพียงอย่างเดียวไม่เพียงพอที่จะตัดสินผลผูกพัน</p></article><article class="panel knowledge"><h3>หนังสือเวียน ≠ กฎหมายเสมอไป</h3><p>ต้องตรวจสอบผู้ออก ผู้รับ วัตถุประสงค์ และฐานอำนาจ หนังสือเวียนอาจเป็นเพียงแนวปฏิบัติภายใน จึงไม่ควรสรุปว่าผูกพันประชาชนเหมือนบทบัญญัติกฎหมายทุกกรณี</p><p>คำพิพากษาและความเห็นทางกฎหมายมีบทบาทต่างจากบทบัญญัติ ต้องพิจารณาขอบเขตผลผูกพันและข้อเท็จจริงของแต่ละเรื่อง</p></article><article class="panel knowledge"><h3>“มีอำนาจ” กับ “มีหน้าที่”</h3><p>“มีอำนาจ” โดยทั่วไปเป็นการมอบอำนาจให้ดำเนินการภายในขอบเขต ส่วน “มีหน้าที่” กำหนดภาระที่ต้องปฏิบัติเมื่อครบเงื่อนไข</p><p>การมีอำนาจไม่ได้หมายความว่ามีดุลพินิจอิสระเสมอไป และการมีหน้าที่ก็อาจยังมีดุลพินิจเลือกวิธีดำเนินการ ต้องอ่านทั้งมาตราและกฎหมายที่เกี่ยวข้อง</p><button class="secondary" data-ask="คำว่า ให้มีอำนาจ กับ มีหน้าที่ต้องดำเนินการ แตกต่างกันอย่างไร">นำไปตั้งคำถาม →</button></article><article class="panel knowledge"><h3>ค้นจากแหล่งข้อมูลทางการ</h3><p><a href="https://ratchakitcha.soc.go.th/" target="_blank" rel="noopener">ราชกิจจานุเบกษา ↗</a><br>ตรวจสอบข้อความประกาศและวันมีผลใช้บังคับ</p><p><a href="https://www.krisdika.go.th/" target="_blank" rel="noopener">สำนักงานคณะกรรมการกฤษฎีกา ↗</a><br>ศึกษาตัวบทและข้อมูลกฎหมาย</p><p><a href="https://www.coj.go.th/" target="_blank" rel="noopener">สำนักงานศาลยุติธรรม ↗</a><br>ข้อมูลเกี่ยวกับศาลและบริการค้นคว้าที่เกี่ยวข้อง</p><small>ลิงก์เหล่านี้เป็นจุดเริ่มต้นการค้นคว้า แอปไม่ได้ตรวจสอบกฎหมายฉบับปัจจุบันให้อัตโนมัติ</small></article></div>`}
function render(page='home'){currentPage=page;$('#content').innerHTML=page==='home'?home():page==='library'?library():page==='principles'?intro('หลักการตีความ 6 มิติ','อ่านกฎหมายให้รอบด้าน โดยพิจารณาทั้งตัวบท เจตนารมณ์ และการใช้บังคับ')+`<div class="knowledge-grid">${principles.map((p,i)=>`<article class="panel knowledge"><span class="eyebrow">0${i+1} · ${p[1]}</span><h3 style="margin-top:15px">การตีความ${p[0]}</h3><p>${p[2]}</p></article>`).join('')}<div class="panel knowledge wide"><p>หากมีแนวตีความหลายแนว ต้องแสดงเหตุผลและประเมินน้ำหนักตามตัวบทและหลักฐาน โดยไม่สรุปเป็นข้อยุติเมื่อยังไม่มีฐานรองรับ</p></div></div>`:page==='instructions'?intro('อาจารย์กฎหมายในแบบของคุณ','ชุดคำสั่งที่เรียบเรียงจากแนวทางของคุณ สำหรับ ChatGPT Projects หรือ Custom GPT')+`<div class="panel knowledge"><h3>Custom Instructions — พร้อมคัดลอกใช้งาน</h3><p>วางข้อความนี้ในช่อง Instructions ของ Project หรือ Custom GPT แล้วเพิ่มเอกสารอ้างอิงที่ตรวจสอบได้ตามบริบทงานของคุณ</p><div class="toolbar"><button class="primary" id="copy-instructions">คัดลอก Instructions</button><button class="secondary" id="download-instructions">ดาวน์โหลด .txt ↓</button></div><textarea readonly class="instructiontext" aria-label="Custom Instructions">${esc(instructions)}</textarea></div>`:intro('ประเด็นที่บันทึกไว้','กลับมาศึกษาและต่อยอดการวิเคราะห์ของคุณ ข้อมูลเก็บเฉพาะในเบราว์เซอร์นี้')+(saved.length?saved.map((s,i)=>`<article class="panel saved-item"><h3>${esc(s.title)}</h3><small>${esc(s.mode)} · ${new Date(s.date).toLocaleDateString('th-TH')}</small><div class="saved-actions"><button class="secondary" data-view="${i}">เปิดชุดคำสั่ง</button><button class="textbutton" data-delete="${i}">ลบประเด็น</button></div></article>`).join(''):`<div class="panel empty"><h2>เก็บประเด็นแรกของคุณ</h2><p>เริ่มตั้งคำถาม แล้วกด “บันทึกประเด็น” ในหน้าชุดคำสั่ง</p><button class="primary" data-page="home">เริ่มต้นวิเคราะห์ →</button></div>`);$('#breadcrumb').innerHTML=`พื้นที่ทำงาน <i>/</i> <strong>${labels[page]}</strong>`;document.querySelectorAll('nav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#save-count').textContent=saved.length;wire();}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').style.display='none',3500)}
async function copy(s){try{await navigator.clipboard.writeText(s);toast('คัดลอกเรียบร้อยแล้ว')}catch{toast('เบราว์เซอร์ไม่อนุญาตให้คัดลอก กรุณาเลือกข้อความแล้วคัดลอกเอง')}}
function displayPrompt(p,t){currentPrompt=p;currentTitle=t;$('#result-text').value=p;$('#result').showModal()}
function wire(){if($('#question')){$('#question').oninput=e=>{question=e.target.value;$('#counter').textContent=`${question.length.toLocaleString()} / 12,000`};$('#upload').onclick=()=>$('#file').click();$('#file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(!/\.(txt|md)$/i.test(f.name))return toast('รองรับไฟล์ .txt และ .md เท่านั้น');if(f.size>100000)return toast('ไฟล์ต้องมีขนาดไม่เกิน 100 KB');try{const t=await f.text();if(t.includes('\u0000'))return toast('ไม่สามารถอ่านไฟล์นี้เป็นข้อความได้');doc=t;docName=f.name;render('home');toast('แนบข้อความเรียบร้อยแล้ว')}catch{toast('อ่านไฟล์ไม่สำเร็จ กรุณาลองใหม่')}};$('#analyze').onclick=()=>{if(!question.trim()){toast('กรุณาระบุคำถามหรือประเด็นที่ต้องการวิเคราะห์');$('#question').focus();return}const p=instructions+`\n\n--- บริบทการวิเคราะห์ ---\nกลุ่มผู้อ่าน: ${modes[mode]}\n${mode===0?'อธิบายศัพท์กฎหมายด้วยภาษาง่ายและตัวอย่างใกล้ตัว':mode===1?'เน้นฐานอำนาจ หน้าที่ ขั้นตอน ระยะเวลา และความเสี่ยงของผู้ปฏิบัติงาน':'เน้นเหตุผล หลักนิติศาสตร์ แนวตีความที่แตกต่าง และน้ำหนักหลักฐาน'}\n\nคำถามหรือข้อเท็จจริงจากผู้ใช้:\n${question}\n${doc?`\nเอกสารประกอบ (${docName}) — ยังไม่ได้ตรวจสอบกับต้นฉบับทางการ:\n<user_document>\n${doc}\n</user_document>`:''}\n\nโปรดตอบตามกรอบ 6 ประเด็น แยกข้อมูลที่ตรวจสอบแล้วออกจากข้อมูลที่ยังไม่สามารถยืนยันได้ หากไม่มีเครื่องมือเข้าถึงแหล่งทางการ ห้ามอ้างว่าได้ตรวจสอบฉบับปัจจุบันแล้ว`;displayPrompt(p,question)}}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){render(b.dataset.page);window.scrollTo({top:0,behavior:'smooth'})}if(b.dataset.mode!==undefined){mode=+b.dataset.mode;render('home')}if(b.dataset.example!==undefined){question=examples[+b.dataset.example];render('home');$('#question').focus()}if(b.id==='remove-doc'){doc='';docName='';render('home')}if(b.dataset.ask){question=b.dataset.ask;render('home');$('#question').focus()}if(b.id==='copy-instructions')copy(instructions);if(b.id==='download-instructions'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([instructions],{type:'text/plain;charset=utf-8'}));a.download='Thai-Legal-Wisdom-Instructions.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}if(b.dataset.view!==undefined){const s=saved[+b.dataset.view];displayPrompt(s.prompt,s.title)}if(b.dataset.delete!==undefined){const index=+b.dataset.delete;const previous=saved;saved=saved.filter((_,i)=>i!==index);if(persist())render('saved');else saved=previous}});
function persist(){try{localStorage.setItem('tlw-saved',JSON.stringify(saved));$('#save-count').textContent=saved.length;return true}catch{toast('พื้นที่จัดเก็บไม่พร้อมใช้งาน กรุณาคัดลอกข้อความเก็บไว้');return false}}
$('#close-result').onclick=()=>$('#result').close();$('#copy-result').onclick=()=>copy(currentPrompt);$('#save-result').onclick=()=>{if(saved.some(s=>s.prompt===currentPrompt))return toast('บันทึกประเด็นนี้ไว้แล้ว');saved.unshift({title:currentTitle,prompt:currentPrompt,mode:modes[mode],date:new Date().toISOString()});if(persist())toast('บันทึกประเด็นเรียบร้อยแล้ว');else saved.shift()};$('#open-chat').onclick=()=>{if(currentPrompt.length>6500){copy(currentPrompt);window.open('https://chatgpt.com/','_blank','noopener');toast('เปิด ChatGPT แล้ว กรุณาวางชุดคำสั่งที่คัดลอกไว้')}else window.open('https://chatgpt.com/?q='+encodeURIComponent(currentPrompt),'_blank','noopener')};document.querySelector('.brand').onclick=e=>{e.preventDefault();render('home')};render();
